import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    static boolean vowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        // pre[i] = qualifying strings among the first i.
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) {
            String s = next();
            pre[i + 1] = pre[i] + (vowel(s.charAt(0)) && vowel(s.charAt(s.length() - 1)) ? 1 : 0);
        }
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            String token = next();
            int dash = token.indexOf('-');
            int l = Integer.parseInt(token.substring(0, dash)), r = Integer.parseInt(token.substring(dash + 1));
            if (k > 0) sb.append(' ');
            sb.append(pre[r] - pre[l - 1]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func vowel(c byte) bool { return strings.IndexByte("aeiou", c) >= 0 }

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := int(nextInt()), int(nextInt())
	// pre[i] = qualifying strings among the first i.
	pre := make([]int, n+1)
	for i := 0; i < n; i++ {
		s := nextToken()
		pre[i+1] = pre[i]
		if vowel(s[0]) && vowel(s[len(s)-1]) {
			pre[i+1]++
		}
	}
	var out []byte
	for k := 0; k < q; k++ {
		lo, hi, _ := strings.Cut(nextToken(), "-")
		l, _ := strconv.Atoi(lo)
		r, _ := strconv.Atoi(hi)
		if k > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(pre[r]-pre[l-1]), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
